func (this *Text) Insert(string_ string) {
	this.CheckWidget()
	if string_ == jrt.NullString {
		this.Error(ERROR_NULL_ARGUMENT)
	}
	this.ClearSegments(true)
	var buffer []int8 = gtk.ConverterWcsToMbcs(string_, false)
	if (this.style & SINGLE) != 0 {
		var start []int32 = make([]int32, 1)
		var end []int32 = make([]int32, 1)
		gtk.GTKGtk_editable_get_selection_bounds(this.Handle, start, end)
		gtk.GTKGtk_editable_delete_selection(this.Handle)
		gtk.GTKGtk_editable_insert_text(this.Handle, buffer, int32(len(buffer)), start)
		gtk.GTKGtk_editable_set_position(this.Handle, start[0])
	} else {
		var start []int8 = make([]int8, TextITER_SIZEOF)
		var end []int8 = make([]int8, TextITER_SIZEOF)
		if gtk.GTKGtk_text_buffer_get_selection_bounds(this.bufferHandle, start, end) {
			gtk.GTKGtk_text_buffer_delete(this.bufferHandle, start, end)
		}
		gtk.GTKGtk_text_buffer_insert(this.bufferHandle, start, buffer, int32(len(buffer)))
		gtk.GTKGtk_text_buffer_place_cursor(this.bufferHandle, start)
		this.ScrollIfNotVisible(start, nil, true)
	}
	this.ApplySegments()
}

